#pragma once

/**
 * @file security_alerts.hpp
 * @brief This header file defines the SecurityAlert structure and related enumerations.
 *
 * The SecurityAlert structure represents a security alert generated by the engine, including its type,
 * severity, agent ID, triggering sequence number, and failure count. The AlertType and AlertSeverity
 * enumerations define the possible types and severities of security alerts.
 *
 * @note The implementation of any related functions or methods is expected to be provided in a corresponding source file (e.g., security_alerts.cpp).
 *
 * @author Roberto Garzone
 * @date 2026-09-03
 */

#include <cstddef>
#include <cstdint>

namespace sentinelgrid::engine {

	/**
	 * @brief An enumeration representing the types of security alerts.
	 */
	enum class AlertType : std::uint32_t {
		repeated_login_failure = 1,
		malicious_request = 2
	};
	
	/**
	 * @brief An enumeration representing the severities of security alerts.
	 */
	enum class AlertSeverity : std::uint32_t {
		low = 1,
		medium = 2,
		high = 3,
		critical = 4
	};

	/**
	 * @brief A structure representing a security alert.
	 *
	 * The SecurityAlert structure contains information about a security alert generated by the engine,
	 * including the alert type, severity, agent ID, triggering sequence number, and failure count.
	 */
	struct SecurityAlert {
		AlertType type;
		AlertSeverity severity;

		std::uint32_t agent_id;
		std::uint64_t triggering_sequence;
		std::uint32_t failure_count;
	};
}